mapper.select:
SELECT er.id, er.application_id, s.name AS student_name, s.student_no AS student_no, gt.type_name AS type_name, er.total_score, er.score_rank, CASE WHEN ga.special_type > 0 THEN 1 ELSE 0 END AS is_special, gl.level_name, gl.amount AS grant_amount, er.evaluate_time FROM evaluation_result er INNER JOIN grant_application ga ON er.application_id = ga.id INNER JOIN student s ON er.student_id = s.id INNER JOIN grant_type gt ON ga.type_id = gt.id LEFT JOIN grant_level gl ON er.level_id = gl.id
AND ga.type_id = #{typeId}
AND (s.name LIKE CONCAT('%', #{keyword}, '%') OR s.student_no LIKE CONCAT('%', #{keyword}, '%'))
AND s.counselor_id = #{counselorId}
ORDER BY er.score_rank ASC
